{
  "findings": [
    {
      "check_id": "CKV_GCP_82",
      "title": "Bigtable instance uses HDD storage type instead of SSD",
      "resource": "google_bigtable_instance.pass",
      "severity": "LOW",
      "explanation": "The Bigtable cluster is configured with 'HDD' storage. While not a direct security vulnerability like lack of encryption, Google Cloud recommends 'SSD' for production workloads due to better performance and reliability characteristics, which indirectly supports availability (a pillar of security). However, the primary security control (KMS encryption) is present."
    }
  ],
  "patched_code": "resource "google_bigtable_instance" "pass" {
  name = "tf-instance"
  deletion_protection = true
  cluster {
    cluster_id   = "tf-instance-cluster"
    num_nodes    = 1
    storage_type = "SSD"
    kms_key_name = google_kms_crypto_key.example.name
  }

  labels = {
    my-label = "prod-label"
  }
}
",
  "fix_summary": "Changed the `storage_type` from `HDD` to `SSD` in the Bigtable cluster configuration to align with best practices for production-grade infrastructure reliability and performance."
}
